#include <stdio.h>
int recurr(int x[],int y,int t)
{
    int a[t],i,p,m=0;
    for(i=0;i<t;i++)
    {
     if(i>=0&&i<y)
      {
        a[i]=x[i];
      }
     else
      {p=1;
        a[i]=0;
        while(p<=y)
        {
            a[i]=a[i]+a[i-p];
            p++;
        }
      }
    } 
    for(i=0;i<t;i++)
    {
        m=m+a[i];
    }
  return(m);    
}
